import Foundation
import Testing
@testable import BetaKit

/// BetaKit must decode exactly what the API returns: contracts/api/examples is generated by
/// `make contracts` from a real in-process API run.
@Suite struct ContractDecodingTests {
    @Test func analysisExampleDecodes() throws {
        let analysis = try Fixtures.decode(Analysis.self, "api/examples/analysis.json")
        #expect(!analysis.holds.isEmpty)
        #expect(analysis.problem != nil)
        #expect(analysis.colorGroups["yellow"] != nil)
        #expect(analysis.imageUrl.scheme == "https")
    }

    @Test func betaExampleDecodes() throws {
        let beta = try Fixtures.decode(Beta.self, "api/examples/beta.json")
        #expect(beta.status == .ready)
        #expect(!beta.moves.isEmpty)
        #expect(beta.moves.filter(\.isCrux).count == 1)
        #expect(beta.moves.last?.technique == "match")
        #expect(beta.grade?.hasPrefix("V") == true)
        #expect(beta.start?.lh != nil)
    }

    @Test func videoExampleDecodes() throws {
        let video = try Fixtures.decode(Video.self, "api/examples/video.json")
        #expect(video.status == .ready)
        #expect(video.videoUrl != nil)
        #expect(!video.chapters.isEmpty)
        #expect(video.chapters.map(\.startS) == video.chapters.map(\.startS).sorted())
    }

    @Test func feedbackAndHealthDecode() throws {
        let receipt = try Fixtures.decode(FeedbackReceipt.self, "api/examples/feedback.json")
        #expect(receipt.kind == .sent)
        let health = try Fixtures.decode(Health.self, "api/examples/health.json")
        #expect(health.status == "ok")
    }

    @Test func paletteMatchesTheContract() throws {
        struct Contract: Decodable { let limbs: [String: String]; let accent: String }
        let contract = try JSONDecoder().decode(Contract.self, from: Fixtures.contract("palette.json"))
        for limb in Limb.allCases {
            #expect(Palette.limbHex[limb] == contract.limbs[limb.rawValue])
        }
        #expect(Palette.accentHex == contract.accent)
    }

    @Test func requestsEncodeSnakeCase() throws {
        let selection = ProblemSelection(startHoldIds: [1], topHoldId: 9, holdIds: nil, color: "yellow")
        let json = String(decoding: try BetaJSON.encoder.encode(selection), as: UTF8.self)
        #expect(json.contains("\"start_hold_ids\""))
        #expect(json.contains("\"top_hold_id\""))

        let profile = ClimberProfile(heightCm: 170, apeIndexCm: 2, maxGrade: "V4", style: .dynamic)
        let body = String(decoding: try BetaJSON.encoder.encode(BetaRequestBody(profile: profile)), as: UTF8.self)
        #expect(body.contains("\"height_cm\""))
        #expect(body.contains("\"dynamic\""))
    }

    @Test func profileRoundTripsThroughRawValue() {
        let profile = ClimberProfile(heightCm: 182, apeIndexCm: -1, maxGrade: "V6", style: .static)
        #expect(ClimberProfile(rawValue: profile.rawValue) == profile)
        #expect(ClimberProfile(rawValue: "not json") == nil)
    }
}
